pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime, uint128 valueSent) public {
        blockNum = bound(blockNum, 1, 1_000_000_000);
        warpTime = bound(warpTime, 1, type(uint32).max);
        valueSent = uint128(bound(valueSent, 10 ether, 10 ether));

        vm.roll(blockNum);
        vm.warp(warpTime);

        address actor = makeAddr("actor");
        vm.deal(actor, valueSent);

        vm.prank(actor);
        (bool success,) = address(c).call{value: valueSent}("");
        require(success, "Fallback call failed");

        if (blockNum % 15 != 0) {
            assertTrue(address(c).balance > 0);
        }
    }
}
